src/interfaces/IStandardManager.sol.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.13;

import {IAsset} from "./IAsset.sol";
import {IPerpAsset} from "./IPerpAsset.sol";
import {IBaseManager} from "./IBaseManager.sol";
import {IOptionAsset} from "./IOptionAsset.sol";
import {ISpotFeed} from "./ISpotFeed.sol";
import {IForwardFeed} from "./IForwardFeed.sol";
import {IVolFeed} from "./IVolFeed.sol";

interface IStandardManager is IBaseManager {
  enum AssetType {
    NotSet,
    Option,
    Perpetual,
    Base
  }

  struct AssetDetail {
    bool isWhitelisted;
    AssetType assetType;
    uint marketId;
  }

  /**
   * @dev a standard manager portfolio contains multiple marketHoldings assets, each marketHolding contains multiple derivative type
   */
  struct StandardManagerPortfolio {
    // @dev each marketHolding take care of 1 base asset, for example ETH and BTC.
    MarketHolding[] marketHoldings;
    int cash;
  }

  struct MarketHolding {
    uint marketId;
    /// base position: doesn't contribute to margin, but increase total portfolio mark to market
    uint basePosition;
    /// perp position detail
    IPerpAsset perp;
    int perpPosition;
    /// option position detail
    IOptionAsset option;
    ExpiryHolding[] expiryHoldings;
    // sum of all short positions and abs(perps) for the market.
    // used to increase margin requirement if stable price depegs.
    uint depegPenaltyPos;
  }

  /// @dev contains portfolio struct for single expiry assets
  struct ExpiryHolding {
    /// array of option hold in this expiry
    Option[] options;
    /// expiry timestamp
    uint expiry;
    /// sum of all call positions, used to determine if portfolio max loss is bounded
    int netCalls;
    /// temporary variable to count how many options is used
    uint numOptions;
    /// total short position size. should be positive
    uint totalShortPositions;
  }

  struct Option {
    uint strike;
    int balance;
    bool isCall;
  }

  /// @dev Struct for Perp Margin Requirements
  struct PerpMarginRequirements {
    /// @dev minimum amount of spot required as maintenance margin for each perp position
    uint mmPerpReq;
    /// @dev minimum amount of spot required as initial margin for each perp position
    uint imPerpReq;
  }

  /// @dev Struct for Option Margin Parameters
  struct OptionMarginParams {
    /// @dev Percentage of spot to add to initial margin if option is ITM. Decreases as option becomes more OTM.
    uint maxSpotReq;
    /// @dev Minimum amount of spot price to add as initial margin.
    uint minSpotReq;
    /// @dev Minimum amount of spot price to add as maintenance margin.
    uint mmCallSpotReq;
    /// @dev Minimum amount of spot to add for maintenance margin
    uint mmPutSpotReq;
    /// @dev Minimum amount of mtm to add for maintenance margin for puts
    uint MMPutMtMReq;
    /// @dev Scaler applied to forward by amount if max loss is unbounded, when calculating IM
    uint unpairedIMScale;
    /// @dev Scaler applied to forward by amount if max loss is unbounded, when calculating MM
    uint unpairedMMScale;
    /// @dev Scale the MM for a put as minimum of IM
    uint mmOffsetScale;
  }

  struct DepegParams {
    uint threshold;
    uint depegFactor;
  }

  struct OracleContingencyParams {
    uint perpThreshold;
    uint optionThreshold;
    uint baseThreshold;
    uint OCFactor;
  }

  struct BaseMarginParams {
    uint marginFactor;
    uint IMScale;
  }

  function assetDetails(IAsset asset) external view returns (AssetDetail memory);

  ///////////////
  //   Errors  //
  ///////////////

  /// @dev Market is not created yet
  error SRM_MarketNotCreated();

  /// @dev Caller is not the Accounts contract
  error SRM_NotAccounts();

  /// @dev Not whitelist manager
  error SRM_NotWhitelistManager();

  /// @dev Not supported asset
  error SRM_UnsupportedAsset();

  error SRM_TooManyAssets();

  /// @dev Account is under water, need more cash
  error SRM_PortfolioBelowMargin();

  /// @dev Invalid Parameters for perp margin requirements
  error SRM_InvalidPerpMarginParams();

  error SRM_InvalidOptionMarginParams();

  /// @dev Forward Price for an asset is 0
  error SRM_NoForwardPrice();

  /// @dev Invalid depeg parameters
  error SRM_InvalidDepegParams();

  /// @dev Invalid Oracle contingency params
  error SRM_InvalidOracleContingencyParams();

  /// @dev Invalid base asset margin discount factor
  error SRM_InvalidBaseDiscountFactor();

  /// @dev No negative cash
  error SRM_NoNegativeCash();

  ///////////////////
  //    Events     //
  ///////////////////

  event MarketCreated(uint marketId, string marketName);

  event AssetWhitelisted(address asset, uint marketId, AssetType assetType);

  event OraclesSet(uint marketId, address spotOracle, address forwardOracle, address volFeed);

  event PerpMarginRequirementsSet(uint marketId, uint perpMMRequirement, uint perpIMRequirement);

  event OptionMarginParamsSet(
    uint marketId,
    uint maxSpotReq,
    uint minSpotReq,
    uint mmCallSpotReq,
    uint mmPutSpotReq,
    uint MMPutMtMReq,
    uint unpairedIMScale,
    uint unpairedMMScale,
    uint mmOffsetScale
  );

  event BaseMarginParamsSet(uint marketId, uint baseAssetMarginFactor, uint baseAssetIMScale);

  event DepegParametersSet(uint threshold, uint depegFactor);

  event OracleContingencySet(uint prepThreshold, uint optionThreshold, uint baseThreshold, uint OCFactor);

  event StableFeedUpdated(address stableFeed);

  event BorrowingEnabled(bool borrowingEnabled);
}

src/interfaces/ISubAccounts.sol.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.18;

import {IERC721} from "openzeppelin/token/ERC721/IERC721.sol";
import {IAsset} from "./IAsset.sol";
import {IManager} from "./IManager.sol";

import {IAllowances} from "./IAllowances.sol";

// For full documentation refer to src/SubAccounts.sol";
interface ISubAccounts is IERC721 {
  struct BalanceAndOrder {
    // balance of (asset, subId)
    int240 balance;
    // index in heldAssets() or getAccountBalances()
    uint16 order;
  }

  struct HeldAsset {
    IAsset asset;
    uint96 subId;
  }

  struct AssetDelta {
    IAsset asset;
    uint96 subId;
    int delta;
  }

  // the struct is used to easily manage 2 dimensional array
  struct AssetDeltaArrayCache {
    uint used;
    AssetDelta[100] deltas;
  }

  /////////////////////////
  // Memory-only Structs //
  /////////////////////////

  struct AssetBalance {
    IAsset asset;
    // adjustments will revert if > uint96
    uint subId;
    // base layer only stores up to int240
    int balance;
  }

  struct AssetTransfer {
    // debited by amount
    uint fromAcc;
    // credited by amount
    uint toAcc;
    // asset contract address
    IAsset asset;
    // adjustments will revert if >uint96
    uint subId;
    // reverts if transfer amount > uint240
    int amount;
    // data passed into asset.handleAdjustment()
    bytes32 assetData;
  }

  struct AssetAdjustment {
    uint acc;
    IAsset asset;
    // reverts for subIds > uint96
    uint subId;
    // reverts if transfer amount > uint240
    int amount;
    // data passed into asset.handleAdjustment()
    bytes32 assetData;
  }

  ///////////////////
  // Account Admin //
  ///////////////////

  /**
   * @notice Creates account with new accountId
   * @param owner new account owner
   * @param _manager IManager of new account
   * @return newId ID of new account
   */
  function createAccount(address owner, IManager _manager) external returns (uint newId);

  /**
   * @notice Creates account and gives spender full allowance
   * @dev   @note: can be used to create and account for another user and simultaneously give allowance to oneself
   * @param owner new account owner
   * @param spender give address ERC721 approval
   * @param _manager IManager of new account
   * @return newId ID of new account
   */
  function createAccountWithApproval(address owner, address spender, IManager _manager) external returns (uint newId);

  ///////////////
  // Approvals //
  ///////////////

  /**
   * @notice Sets bidirectional allowances for all subIds of an asset.
   *         During a balance adjustment, if msg.sender not ERC721 approved or owner,
   *         asset allowance + subId allowance must be >= amount
   * @param accountId ID of account
   * @param delegate address to assign allowance to
   * @param allowances positive and negative amounts for each asset
   */
  function setAssetAllowances(uint accountId, address delegate, IAllowances.AssetAllowance[] memory allowances)
    external;

  /**
   * @notice Sets bidirectional allowances for a specific subId.
   *         During a balance adjustment, the subId allowance is decremented first
   * @param accountId ID of account
   * @param delegate address to assign allowance to
   * @param allowances positive and negative amounts for each (asset, subId)
   */
  function setSubIdAllowances(uint accountId, address delegate, IAllowances.SubIdAllowance[] memory allowances)
    external;

  /////////////////////////
  // Balance Adjustments //
  /////////////////////////

  /**
   * @notice Transfer an amount from one account to another for a specific (asset, subId)
   * @param assetTransfer (fromAcc, toAcc, asset, subId, amount)
   * @param managerData data passed to managers of both accounts
   */
  function submitTransfer(AssetTransfer memory assetTransfer, bytes memory managerData) external returns (uint tradeId);

  /**
   * @notice Batch several transfers
   *         Gas efficient when modifying the same account several times,
   *         as _managerHook() is only performed once per account
   * @param assetTransfers array of (fromAcc, toAcc, asset, subId, amount)
   * @param managerData data passed to every manager involved in trade
   */
  function submitTransfers(AssetTransfer[] memory assetTransfers, bytes memory managerData)
    external
    returns (uint tradeId);

  /**
   * @notice Asymmetric balance adjustment reserved for assets
   *         Must still pass both _managerHook()
   * @param adjustment asymmetric adjustment of amount for (asset, subId)
   * @param triggerAssetHook true if the adjustment need to be routed to Asset's custom hook
   * @param managerData data passed to manager of account
   */
  function assetAdjustment(AssetAdjustment memory adjustment, bool triggerAssetHook, bytes memory managerData)
    external
    returns (int postBalance);

  /**
   * @notice Assymetric balance adjustment reserved for managers
   *         Must still pass both _assetHook()
   * @param adjustment assymetric adjustment of amount for (asset, subId)
   */
  function managerAdjustment(AssetAdjustment memory adjustment) external returns (int postBalance);

  //////////
  // View //
  //////////

  /**
   * @dev return the manager address of the account
   * @param accountId ID of account
   */
  function manager(uint accountId) external view returns (IManager);

  /**
   * @dev return the tradeId for when the account was last interacted with
   * @param accountId ID of account
   */
  function lastAccountTradeId(uint accountId) external view returns (uint lastTradeId);

  /**
   * @dev return amount of asset in the account, and the order (index) of the asset in the asset array
   * @param accountId ID of account
   * @param asset IAsset of balance
   * @param subId subId of balance
   */
  function balanceAndOrder(uint accountId, IAsset asset, uint subId)
    external
    view
    returns (int240 balance, uint16 order);

  /**
   * @notice Gets an account's balance for an (asset, subId)
   * @param accountId ID of account
   * @param asset IAsset of balance
   * @param subId subId of balance
   */
  function getBalance(uint accountId, IAsset asset, uint subId) external view returns (int balance);

  /**
   * @notice Gets a list of all asset balances of an account
   * @dev can use balanceAndOrder() to get the index of a specific balance
   * @param accountId ID of account
   */
  function getAccountBalances(uint accountId) external view returns (AssetBalance[] memory assetBalances);

  /**
   * @dev get unique assets from heldAssets.
   *      heldAssets can hold multiple entries with same asset but different subId
   * @param accountId ID of account
   * @return uniqueAssets list of address
   */
  function getUniqueAssets(uint accountId) external view returns (address[] memory uniqueAssets);

  ////////////
  // Events //
  ////////////

  /**
   * @dev Emitted account created or split
   */
  event AccountCreated(address indexed owner, uint indexed accountId, address indexed manager);

  /**
   * @dev Emitted account burned
   */
  event AccountBurned(address indexed owner, uint indexed accountId, address indexed manager);

  /**
   * @dev Emitted when account manager changed
   */
  event AccountManagerChanged(uint indexed accountId, address indexed oldManager, address indexed newManager);

  /**
   * @dev Emitted when user invalidate set of nonces
   */
  event UnorderedNonceInvalidated(address owner, uint wordPos, uint mask);

  event AssetTransferred(
    uint indexed fromAcc, uint indexed toAcc, IAsset asset, uint subId, int amount, bytes32 assetData, uint tradeId
  );

  /**
   * @dev Emitted during any balance change event. This includes:
   *      1. single transfer
   *      2. batch transfer
   *      3. transferAll / merge / split
   *      4. manager or asset initiated adjustments
   *      PreBalance + amount not necessarily = postBalance
   */
  event BalanceAdjusted(
    uint indexed accountId,
    address indexed manager,
    bytes32 indexed assetAndSubId,
    int amount,
    int preBalance,
    int postBalance,
    uint tradeId
  );

  ////////////
  // Errors //
  ////////////

  error AC_OnlyManager();

  error AC_OnlyAsset();

  error AC_TooManyTransfers();

  error AC_NotOwnerOrERC721Approved(address spender, uint accountId, address owner, IManager manager, address approved);

  error AC_CannotTransferAssetToOneself(address caller, uint accountId);

  error AC_CannotChangeToSameManager(address caller, uint accountId);

  error AC_InvalidPermitSignature();

  error AC_SignatureExpired();

  /// @dev nonce already used.
  error AC_InvalidNonce();
}

